const now = new Date();
const allLeads = $input.all().map(i => i.json);

const parseDate = (s) => {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const hoursSince = (dateStr) => {
  const d = parseDate(dateStr);
  if (!d) return 9999;
  return (now - d) / (1000 * 60 * 60);
};

// Day-matched templates — personalized by name + service, no AI cost
const templates = {
  0: (fn, svc) => (fn ? 'Hi ' + fn + ',' : 'Hi,') + ' just following up on your ' + svc + ' request with Valfin Tech. Ready to lock in your free inspection? Reply YES or call us anytime.',
  1: (fn, svc) => (fn ? 'Hey ' + fn + ',' : 'Hey,') + ' we still have openings this week for your ' + svc + ' inspection. Just say the word and we will get you on the calendar. — Valfin Tech',
  2: (fn, svc) => (fn ? fn + ', one' : 'One') + ' last check-in on your roofing request. Reply YES to book your free inspection before slots fill up. — Valfin Tech'
};
const dayLabels = ['Day 1', 'Day 3', 'Day 7'];

const qualifying = [];
for (const lead of allLeads) {
  const status = (lead['Status'] || '').trim();
  const count = parseInt(String(lead['Follow-up Count'] || '0'), 10) || 0;
  if (!['New', 'Contacted'].includes(status)) continue;
  if (count >= 3) continue;

  const raw = String(lead['Phone'] || '').replace(/\D/g, '');
  const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
    : raw.length === 10 ? '+1' + raw : null;
  if (!e164) continue;

  const hours = hoursSince(lead['Last Contact'] || lead['Date Created'] || '');
  const thresholds = { 0: 24, 1: 72, 2: 96 };
  if (hours < thresholds[count]) continue;

  const fn = lead['First Name'] || '';
  const svc = lead['Service Needed'] || 'roofing inspection';
  const msg = templates[count](fn, svc);

  qualifying.push({
    leadId: lead['Lead ID'] || '',
    phone: e164,
    firstName: fn,
    lastName: lead['Last Name'] || '',
    source: lead['Source'] || '',
    email: lead['Email'] || '',
    address: lead['Address'] || '',
    serviceNeeded: svc,
    followUpMessage: msg,
    followUpCount: count + 1,
    newStatus: count >= 2 ? 'Stale' : 'Contacted',
    logChannel: 'SMS',
    logDirection: 'Outbound',
    logHandler: 'System',
    logSummary: 'Follow-up ' + (count + 1) + ' SMS — ' + dayLabels[count],
    logNotes: msg
  });
}
return qualifying.map(q => ({ json: q }));
